#include <bits/stdc++.h>
using namespace std;

int bfs(int start, int n, const vector<vector<int>>& adj, vector<int>& parent, vector<int>& dist) {
    fill(dist.begin(), dist.end(), -1);
    fill(parent.begin(), parent.end(), -1);
    queue<int> q;
    dist[start] = 0;
    q.push(start);
    int far = start;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        if (dist[u] > dist[far]) far = u;
        for (int v : adj[u]) {
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                parent[v] = u;
                q.push(v);
            }
        }
    }
    return far;
}

long long countAtDepth(int start, int parent, int target, const vector<vector<int>>& adj) {
    long long cnt = 0;
    vector<tuple<int, int, int>> st;
    st.push_back({start, parent, 1});
    while (!st.empty()) {
        auto [u, p, d] = st.back();
        st.pop_back();
        if (d == target) {
            cnt++;
            continue;
        }
        if (d > target) continue;
        for (int v : adj[u]) {
            if (v != p) {
                st.push_back({v, u, d + 1});
            }
        }
    }
    return cnt;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<vector<int>> adj(N + 1);
    for (int i = 0; i < N - 1; i++) {
        int x, y;
        cin >> x >> y;
        adj[x].push_back(y);
        adj[y].push_back(x);
    }

    vector<int> parent(N + 1), dist(N + 1);
    int s = bfs(1, N, adj, parent, dist);
    int t = bfs(s, N, adj, parent, dist);
    int D = dist[t];

    vector<int> path;
    for (int cur = t; cur != -1; cur = parent[cur]) {
        path.push_back(cur);
    }
    reverse(path.begin(), path.end());

    long long ans = 0;

    if (D % 2 == 0) {
        int c = path[D / 2];
        int R = D / 2;
        long long total = 0, sumSq = 0;
        for (int nb : adj[c]) {
            long long cnt = countAtDepth(nb, c, R, adj);
            total += cnt;
            sumSq += cnt * cnt;
        }
        ans = (total * total - sumSq) / 2;
    } else {
        int c1 = path[D / 2];
        int c2 = path[D / 2 + 1];
        int R = D / 2;

        long long cnt1 = 0;
        for (int nb : adj[c1]) {
            if (nb != c2) {
                cnt1 += countAtDepth(nb, c1, R, adj);
            }
        }

        long long cnt2 = 0;
        for (int nb : adj[c2]) {
            if (nb != c1) {
                cnt2 += countAtDepth(nb, c2, R, adj);
            }
        }

        ans = cnt1 * cnt2;
    }

    cout << D + 1 << '\n' << ans << '\n';
    return 0;
}
